first_name_map = {}
for gid, members in group_members.items():
    fname_map = {}
    for full_name, email in members.items():
        # Extract first name (split on space, take first token)
        first = full_name.split()[0]
        fname_map[first] = email
    first_name_map[gid] = fname_map

# Verify all expenses have resolvable payer and debtors
missing = []
for exp in expenses:
    gid = exp['group_id']
    fmap = first_name_map.get(gid, {})
    payer = exp['payer']
    if payer not in fmap:
        missing.append((gid, payer, 'payer'))
    for d in exp['debtors']:
        if d not in fmap:
            missing.append((gid, d, 'debtor'))
if missing:
    print("Missing mappings:", missing)
else:
    print("All names resolvable.")

